import assert from 'node:assert/strict';
import { performance } from 'node:perf_hooks';
import { uniqueTags } from '../src/tags.js';

const mode = process.argv[2];
function check(input, expected) {
  const before = [...input];
  const result = uniqueTags(Object.freeze(input));
  assert.ok(Array.isArray(result));
  assert.deepEqual(result, expected);
  assert.deepEqual(input, before);
}
function reference(tags) {
  const seen = new Set();
  return tags.filter(tag => {
    const key = tag.toLowerCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}
if (mode === 'case') {
  check(['JS', 'Node', 'js', 'NODE', 'css'], ['JS', 'Node', 'css']);
  check(['js', 'JS', 'Js', 'jS'], ['js']);
  check(['CSS', 'js', 'css', 'Node', 'JS', 'NODE', 'new'], ['CSS', 'js', 'Node', 'new']);
  check(['', '', 'A', 'a', ' A', ' a', 'a ', 'A ', 'É', 'é', 'Ω', 'ω'], ['', 'A', ' A', 'a ', 'É', 'Ω']);
  check(['__PROTO__', '__proto__', 'Constructor', 'constructor', 'toString', 'TOSTRING'], ['__PROTO__', 'Constructor', 'toString']);
  // Interleave new identities and differently cased repeats, rather than grouping duplicates.
  let state = 123456789;
  const tags = [];
  for (let i = 0; i < 20000; i++) {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    const tag = `Tag-${state % 5000}-x`;
    tags.push(i % 3 === 0 ? tag.toUpperCase() : i % 3 === 1 ? tag.toLowerCase() : tag);
  }
  check(tags, reference(tags));
  check(['a', 'A'], ['a']);
  check(['A', 'a'], ['A']);
} else if (mode === 'preserve') {
  check([], []);
  check(['node', 'js', 'node', 'css', 'js'], ['node', 'js', 'css']);
  check(['z', 'a', 'b', 'a', 'z', 'c'], ['z', 'a', 'b', 'c']);
  check(['', ' ', '', '  ', ' ', 'x', 'x '], ['', ' ', '  ', 'x', 'x ']);
  check(['__proto__', 'constructor', 'toString', '__proto__'], ['__proto__', 'constructor', 'toString']);
} else if (mode === 'speed' || mode === 'benchmark') {
  // Many distinct identities defeat quadratic scans of the accumulated output.
  const count = 200000;
  const first = Array.from({length: count}, (_, i) => `tag-${i}-suffix`);
  const input = mode === 'benchmark' ? first.concat(first.map(s => s.toUpperCase())) : first.concat(first);
  uniqueTags(input.slice(0, 2000));
  const start = performance.now();
  const output = uniqueTags(input);
  const elapsed = performance.now() - start;
  if (mode === 'speed') {
    assert.deepEqual(output, first);
    assert.ok(elapsed < 750, `400,000 tags took ${elapsed.toFixed(1)} ms; expected <750 ms`);
  } else {
    assert.ok(Array.isArray(output));
    console.log(elapsed.toFixed(4));
  }
} else {
  throw new Error(`Unknown mode: ${mode}`);
}
